/** Decode only the single-executable command encoding generated by Rust.
 * This is for display; the interface never executes the returned path. */
export function helperCommandPath(command: string): string | null {
  if (command.length > 4096 || Array.from(command).some((c) => c.charCodeAt(0) < 32)) return null;
  const raw =
    command.startsWith("'") && command.endsWith("'")
      ? command.slice(1, -1).split("'\\''").join("'")
      : command;
  const safe = Array.from(raw).every((c) => /[a-zA-Z0-9/._-]/.test(c));
  const encoded = safe ? raw : `'${raw.split("'").join("'\\''")}'`;
  return raw.startsWith("/") && encoded === command ? raw : null;
}
